import { RequestValidationError } from './RequestValidationError';

type Fields = Record<string, unknown>;

function asFields(source: unknown): Fields {
  if (typeof source !== 'object' || source === null || Array.isArray(source)) {
    return {};
  }
  return source as Fields;
}

export function requireString(source: unknown, field: string): string {
  const value = asFields(source)[field];
  if (typeof value !== 'string') {
    throw new RequestValidationError(`Field "${field}" is required and must be a string`);
  }
  return value;
}

export function optionalString(source: unknown, field: string): string | undefined {
  const value = asFields(source)[field];
  if (value === undefined || value === null) {
    return undefined;
  }
  if (typeof value !== 'string') {
    throw new RequestValidationError(`Field "${field}" must be a string`);
  }
  return value;
}

